import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    coords = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(coords)}
    m = len(coords)

    # Graph: adj[u] stores [v, cap, cost, rev_idx]
    adj: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        adj[u].append([v, cap, cost, len(adj[v])])
        adj[v].append([u, 0, -cost, len(adj[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for s, e, p in jobs:
        add_edge(idx[s], idx[e], 1, -p)

    # Initial potentials via DAG DP (all forward edges go from u to v with u < v)
    INF = 10**18
    h = [INF] * m
    h[0] = 0
    for u in range(m):
        if h[u] == INF:
            continue
        for v, cap, cost, _ in adj[u]:
            if cap > 0 and h[u] + cost < h[v]:
                h[v] = h[u] + cost

    total_cost = 0
    source, sink = 0, m - 1

    for _ in range(k):
        dist = [INF] * m
        dist[source] = 0
        parent_v = [-1] * m
        parent_e = [-1] * m
        pq = [(0, source)]

        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for ei, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + h[u] - h[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_v[v] = u
                        parent_e[v] = ei
                        heapq.heappush(pq, (nd, v))

        if dist[sink] == INF:
            break

        for i in range(m):
            if dist[i] < INF:
                h[i] += dist[i]

        if h[sink] >= 0:
            break

        total_cost += h[sink]
        v = sink
        while v != source:
            u = parent_v[v]
            ei = parent_e[v]
            edge = adj[u][ei]
            edge[1] -= 1
            adj[v][edge[3]][1] += 1
            v = u

    return -total_cost
